/* Eases a counter's shown value toward its target and animates its two drifting digits. */
/* Ported from rac1-decomp (src/overlays/shared/hud_00235960.c: func_L00_00236830), where it is exact; names translated to the US level program. */

typedef struct {
    char pad0[0x8];
    int unk08;
    int *unk0C;
    char pad10[0x38];
    short unk48;
    short unk4A;
    char pad4C[0x4];
    int unk50;
    int unk54;
    int w;
    int h;
    int flags;
    char pad64[0x8];
    int unk6C;
    unsigned char cnt[4];
    int unk74;
    int unk78;
    int unk7C;
    void *unk80;
} HudElem;

extern f32 ConvertIntegerToFloat(s32) __asm__("FUN_001fa6c0");
extern float FUN_001f9988(float);
extern int scale_game_frames(int) __asm__("FUN_001f96f8");
extern int FUN_L00_0023aaa8(char *);
extern s32 truncate_float_to_s32(f32) __asm__("FUN_001fa6d0");

void FUN_L00_00235ea0(HudElem *e) {
    unsigned char *c = e->cnt;
    int v;
    int cap;
    int d;
    int n;
    int x;
    unsigned char t;

    if (e->unk0C != 0) {
        v = *e->unk0C;
        cap = e->unk08;
        if (v < 0) {
            v = 0;
        }
        e->unk78 = v;
        if (cap < v) {
            e->unk78 = cap;
        }
    }
    if (e->unk74 != e->unk78) {
        e->unk7C = scale_game_frames(0xB4);
        if (e->unk6C >= 0x18) {
            x = e->unk74 - e->unk78;
            d = x;
            d = d < 0 ? -d : d;
            if (d != 0) {
                n = truncate_float_to_s32(FUN_001f9988(ConvertIntegerToFloat(d) / 25.0f) * 5.0f);
                n = n < d * scale_game_frames(2) / scale_game_frames(10)
                        ? d * scale_game_frames(2) / scale_game_frames(10)
                        : n;
                if (n >= 0x7A) {
                    n = 0x79;
                } else if (n <= 0) {
                    n = 1;
                }
                c[3] += n;
                t = c[3];
                if (scale_game_frames(2) < t) {
                    n = c[3] / scale_game_frames(2);
                    if (e->unk78 < e->unk74) {
                        e->unk74 = e->unk74 - n;
                    } else {
                        e->unk74 = e->unk74 + n;
                    }
                    c[3] -= n * scale_game_frames(2);
                }
            }
        }
    }
    if (e->unk7C >= scale_game_frames(5)) {
        if (c[0] < scale_game_frames(8)) {
            c[0]++;
        } else if (c[1] < scale_game_frames(8)) {
            c[1]++;
        }
    } else {
        if (c[1] != 0 || c[0] != 0) {
            e->unk6C = 1;
        }
        if (c[1] != 0) {
            c[1]--;
        } else if (c[0] != 0) {
            c[0]--;
        }
    }
    FUN_L00_0023aaa8((char *)e + 0x40);
}
